require 'faye/websocket'
require 'json'
require 'securerandom'
require 'redis'
require 'openssl'
require 'base64'
require 'uri'

module MessageQueue
  class TenantRegistry
    def initialize
      @tenants = {}
      @mutex = Mutex.new
    end

    def register(tenant_id, connection_id, ws)
      @mutex.synchronize do
        @tenants[tenant_id] ||= {}
        @tenants[tenant_id][connection_id] = ws
      end
    end

    def unregister(tenant_id, connection_id)
      @mutex.synchronize do
        @tenants[tenant_id]&.delete(connection_id)
        @tenants.delete(tenant_id) if @tenants[tenant_id]&.empty?
      end
    end

    def connections_for(tenant_id)
      @mutex.synchronize do
        (@tenants[tenant_id] || {}).values
      end
    end

    def find_connection_for_tenant(tenant_id, connection_id)
      @mutex.synchronize do
        @tenants.dig(tenant_id, connection_id)
      end
    end
  end

  class AuthValidator
    HMAC_SECRET = ENV['HMAC_SECRET'] || raise('HMAC_SECRET environment variable must be set')

    def self.validate_token(token)
      return nil if token.nil? || token.empty?
      parts = token.split('.')
      return nil unless parts.length == 3

      header_b64, payload_b64, signature = parts
      expected_sig = OpenSSL::HMAC.hexdigest('SHA256', HMAC_SECRET, "#{header_b64}.#{payload_b64}")

      return nil unless secure_compare(expected_sig, signature)

      payload = JSON.parse(Base64.urlsafe_decode64(payload_b64))
      return nil if payload['exp'] && payload['exp'] < Time.now.to_i
      payload
    rescue
      nil
    end

    def self.secure_compare(a, b)
      return false unless a.bytesize == b.bytesize
      l = a.unpack('C*')
      r = b.unpack('C*')
      result = 0
      l.zip(r) { |x, y| result |= x ^ y }
      result == 0
    end
  end

  class Consumer
    attr_reader :tenant_id, :connection_id, :subscriptions

    def initialize(ws, env, registry)
      @ws = ws
      @env = env
      @registry = registry
      @connection_id = SecureRandom.uuid
      @subscriptions = []
      @authenticated = false
      @tenant_id = nil
      @message_handler = MessageHandler.new(self, registry)
    end

    def authenticate!
      token = extract_token
      payload = AuthValidator.validate_token(token)

      if payload && payload['tenant_id']
        @tenant_id = payload['tenant_id']
        @authenticated = true
        @registry.register(@tenant_id, @connection_id, @ws)
        send_message({ type: 'auth_success', connection_id: @connection_id })
      else
        send_message({ type: 'auth_failed', reason: 'invalid_token' })
        @ws.close(4001, 'Authentication failed')
      end
    end

    def handle_message(data)
      return unless @authenticated
      parsed = JSON.parse(data)
      @message_handler.dispatch(parsed)
    rescue JSON::ParserError
      send_message({ type: 'error', reason: 'invalid_json' })
    end

    def handle_close
      @registry.unregister(@tenant_id, @connection_id) if @tenant_id
      @subscriptions.clear
    end

    def send_message(msg)
      @ws.send(JSON.generate(msg))
    end

    def authorized_for_tenant?(target_tenant)
      @tenant_id == target_tenant
    end

    private

    def extract_token
      query_string = @env['QUERY_STRING'] || ''
      params = URI.decode_www_form(query_string).to_h
      params['token'] || extract_header_token
    end

    def extract_header_token
      auth_header = @env['HTTP_AUTHORIZATION'] || ''
      auth_header.sub(/^Bearer\s+/i, '')
    end
  end

  class MessageHandler
    def initialize(consumer, registry)
      @consumer = consumer
      @registry = registry
    end

    def dispatch(message)
      case message['action']
      when 'subscribe'
        handle_subscribe(message)
      when 'unsubscribe'
        handle_unsubscribe(message)
      when 'publish'
        handle_publish(message)
      when 'direct_message'
        handle_direct_message(message)
      else
        @consumer.send_message({ type: 'error', reason: 'unknown_action' })
      end
    end

    private

    def handle_subscribe(message)
      channel = message['channel']
      return unless valid_channel?(channel)

      tenant_prefix = extract_tenant_prefix(channel)
      unless @consumer.authorized_for_tenant?(tenant_prefix)
        @consumer.send_message({ type: 'error', reason: 'unauthorized_channel' })
        return
      end

      @consumer.subscriptions << channel unless @consumer.subscriptions.include?(channel)
      @consumer.send_message({ type: 'subscribed', channel: channel })
    end

    def handle_unsubscribe(message)
      channel = message['channel']
      @consumer.subscriptions.delete(channel)
      @consumer.send_message({ type: 'unsubscribed', channel: channel })
    end

    def handle_publish(message)
      channel = message['channel']
      payload = message['payload']
      return unless valid_channel?(channel)

      tenant_prefix = extract_tenant_prefix(channel)
      unless @consumer.authorized_for_tenant?(tenant_prefix)
        @consumer.send_message({ type: 'error', reason: 'unauthorized_publish' })
        return
      end

      broadcast_to_channel(channel, payload)
    end

    def handle_direct_message(message)
      target_connection = message['target_connection_id']
      payload = message['payload']

      # Only allow direct messages within the same tenant
      ws = @registry.find_connection_for_tenant(@consumer.tenant_id, target_connection)
      if ws
        ws.send(JSON.generate({
          type: 'direct_message',
          from: @consumer.connection_id,
          payload: payload
        }))
      else
        @consumer.send_message({ type: 'error', reason: 'target_not_found_or_cross_tenant' })
      end
    end

    def broadcast_to_channel(channel, payload)
      tenant_prefix = extract_tenant_prefix(channel)
      connections = @registry.connections_for(tenant_prefix)
      connections.each do |ws|
        ws.send(JSON.generate({
          type: 'channel_message',
          channel: channel,
          payload: payload
        }))
      end
    end

    def valid_channel?(channel)
      return false if channel.nil? || channel.empty?
      channel.match?(/\A[a-zA-Z0-9_\-]+(\.[a-zA-Z0-9_\-]+)*\z/)
    end

    def extract_tenant_prefix(channel)
      channel.split('.').first
    end
  end
end
